{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C27"],
      "claim": "Olcegepant, a large peptide-like CGRP antagonist, has absolute oral bioavailability <1% in humans, directly demonstrating that this structural class can have extremely low oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C23"],
      "claim": "Alvimopan has an absolute oral bioavailability of only 6% in humans, well below the 20% threshold, supporting low oral bioavailability for a related peptidomimetic.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Melagatran has an oral bioavailability of 3–7% in humans, providing direct human evidence of low systemic exposure for a polar peptide-like molecule.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C25"],
      "claim": "Plecanatide, a peptide, exhibits negligible systemic availability after oral administration, showing that peptide-sized molecules with multiple polar residues can have essentially no oral absorption.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C07"],
      "claim": "Octreotide, a cyclic peptide, has an absolute oral bioavailability of only 0.6 ± 0.4% in healthy volunteers, reinforcing that peptide structures generally have very low oral F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C26"],
      "claim": "Aliskiren has a mean absolute oral bioavailability of 2.6% in healthy subjects, providing additional human evidence that even optimized non-peptide drugs with high polarity can remain far below 20% oral F.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is a large acylated peptide/PEG conjugate with many polar and ionizable groups. All highly transferable experimental analogues are peptides or peptidomimetics with measured human oral bioavailability values well below 20% (0.3–14%), and several are <1%. The fasted condition does not provide any basis to expect enhanced absorption. Therefore the query is predicted to have low absolute oral bioavailability at the F ≥ 20% threshold.",
  "evidence_gaps": [
    "No direct human absolute oral bioavailability measurement exists for the query molecule itself.",
    "No experimental data specifically address the query under fasted conditions.",
    "No evidence is available for an absorption-enhancing formulation or prodrug strategy that could raise the query's oral F above 20%."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

